import test from "node:test";
import assert from "node:assert/strict";
import { mean, median } from "../lib/stats.mjs";

test("mean", () => {
  assert.equal(mean([1, 2, 3]), 2);
});

test("median of odd-length input returns the middle value", () => {
  assert.equal(median([3, 1, 2]), 2);
});

test("median of even-length input returns the mean of the middle two", () => {
  assert.equal(median([4, 1, 3, 2]), 2.5);
});

test("median sorts unsorted input", () => {
  assert.equal(median([10, 2, 8, 4, 6]), 6);
});

test("median of a single element", () => {
  assert.equal(median([7]), 7);
});

test("median does not mutate its input", () => {
  const xs = [3, 1, 2];
  median(xs);
  assert.deepEqual(xs, [3, 1, 2]);
});
